using CGSmartK.Application;using CGSmartK.Domain;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace CGSmartK.Web.Controllers;[Authorize(Policy="Employee")]public sealed class ChatController(IAssistantService assistant):Controller { [HttpGet]public IActionResult Index()=>View();[HttpPost]public async Task<IActionResult> Ask(string question,string? workflow,CancellationToken ct){var subject=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value??"unknown";var groups=User.FindAll("groups").Select(x=>x.Value).ToHashSet();var user=new UserAccessContext(subject,groups,Classification.Internal,User.IsInRole("KnowledgeAdministrator"));var request=new ChatRequest(question,user,Guid.NewGuid().ToString("N"),Enum.TryParse<WorkflowKind>(workflow,true,out var w)?w:WorkflowKind.Answer);try{ViewData["Response"]=await assistant.AskAsync(request,ct);}catch(Exception){ViewData["Error"]="The assistant dependency is temporarily unavailable. No ungrounded answer was generated.";}ViewData["Question"]=question;return View("Index");} }
